"""Generate the Rust event-trigger SQL from its Python contract owner."""
from __future__ import annotations

import argparse
from codex_layout import REPOSITORY_ROOT
from codex_sync_entities import event_trigger_sql

SCHEMA_PATH = REPOSITORY_ROOT / 'workspaces/runtime/packages/runtime-store/src/sync_schema.sql'


def generated_schema(source: str) -> str:
    from codex_entity_contracts import EVENT_WINDOW
    before, rest = source.split('-- section: runtime_events\n', 1)
    _, after = rest.split('-- section: runtime_agents\n', 1)
    events = (
        '-- Generated by studio_api.generate_sync_schema; owner: '
        'codex_sync_entities.event_trigger_sql / codex_entity_contracts.EVENT_WINDOW.\n'
        f'-- event-window-size: {EVENT_WINDOW}\n'
        'CREATE INDEX IF NOT EXISTS runtime_event_created_id ON runtime_events(created DESC,id);\n'
        + '\n'.join(event_trigger_sql(operation) + ';' for operation in ('INSERT', 'UPDATE', 'DELETE'))
        + '\n\n'
    )
    return before + '-- section: runtime_events\n' + events + '-- section: runtime_agents\n' + after


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    arguments = parser.parse_args()
    source = SCHEMA_PATH.read_text()
    expected = generated_schema(source)
    if arguments.check:
        if expected != source:
            parser.exit(1, 'Rust event trigger SQL differs from codex_sync_entities.event_trigger_sql; '
                        'run python -m studio_api.generate_sync_schema.\n')
    else:
        SCHEMA_PATH.write_text(expected)


if __name__ == '__main__':
    main()
